requirements=[('RF01','Gestionar habitaciones','Registrar número único, capacidad entera positiva y orientación. Editar sin invalidar reservas o estadías vigentes.','CU02','Habitacion','habitaciones'),('RF02','Registrar e identificar huéspedes','Guardar identificación única, nombres y apellidos; seleccionar huéspedes existentes para evitar duplicarlos. Asociar cada pasajero a su estadía.','CU03, CU04','Huesped, EstadiaHuesped','huespedes, checkin'),('RF03','Consultar ocupación y disponibilidad','Mostrar ocupación actual y habitaciones compatibles con fechas y cantidad de pasajeros. Considerar reservas vigentes y estadías activas.','CU04, CU05, CU09, CU11','Habitacion, Reserva, Estadia','disponibilidad'),('RF04','Registrar check-in','Permitir ingreso con o sin reserva. Verificar habitación, intervalo y todos los pasajeros; crear estadía activa y asignaciones individuales.','CU04','Estadia, EstadiaHuesped','checkin'),('RF05','Registrar check-out','Seleccionar estadía activa, revisar la cuenta y confirmar la salida. Conservar historial y liberar ocupación.','CU06','Estadia, EstadiaHuesped','checkout'),('RF06','Calcular costos por pasajero','Obtener huéspedes de la estadía, aplicar la regla de cobro y mostrar cada costo y total. Conservar los resultados individuales.','CU06, CU07','EstadiaHuesped','checkout'),('RF07','Gestionar usuarios y perfiles','Registrar usuarios, asignar Administrador o Encargado, controlar operaciones por perfil y estado activo.','CU01, CU08','Usuario, Rol','acceso, usuarios'),('RF08','Gestionar reservas','Registrar titular, habitación, fechas y cantidad. Modificar o cancelar sólo reservas registradas; comprobar disponibilidad antes de guardar.','CU09, CU11, CU12','Reserva, Habitacion, Huesped','reservas'),('RF09','Generar informes','Consultar ocupación y reservas para un período; mostrar habitación, fechas, pasajeros y estado; representar también resultados vacíos.','CU10','Reserva, Estadia, Habitacion','informes')]
specs={
'CU01':('Administrador y Encargado','Usuario registrado y activo.','1. Ingresar identificación y credencial.\n2. Validar identidad y estado.\n3. Recuperar rol y permisos.\n4. Abrir sesión y navegación autorizada.','A1. Credencial incorrecta o usuario inactivo: rechazar el ingreso y permitir corregir.','Sesión activa con el perfil asignado.','En el prototipo se selecciona un usuario demo; no se implementa la autenticación productiva.'),
'CU02':('Administrador','Sesión con permiso de administración.','1. Seleccionar registro nuevo o habitación existente.\n2. Ingresar número, capacidad y orientación.\n3. Validar número único y capacidad.\n4. Si es edición, revisar registros vigentes.\n5. Guardar y actualizar el listado.','A1. Datos inválidos o número duplicado: corregir.\nA2. Habitación con reserva registrada o estadía activa: no modificar sus características en la propuesta.','Habitación registrada o actualizada.','RF01; la restricción de edición es una propuesta para proteger asignaciones existentes.'),
'CU03':('Encargado; Administrador por herencia de interacciones','Sesión con permiso.','1. Ingresar identificación, nombres y apellidos.\n2. Buscar coincidencia de identificación.\n3. Registrar un nuevo huésped.\n4. Mostrar el registro para seleccionarlo en reserva o check-in.','A1. Identificación ya existente: informar y seleccionar el huésped registrado.\nA2. Datos incompletos: corregir.','Huésped identificado sin duplicación.','El tipo de identificación se valida en la entrevista; no se exige RUT sin evidencia del caso.'),
'CU04':('Encargado; Administrador por herencia de interacciones','Sesión con permiso; huéspedes registrados. Si se usa reserva, debe estar REGISTRADA.','1. Seleccionar reserva o ingreso directo.\n2. Definir habitación y fechas o recuperar las de la reserva.\n3. Identificar a todos los huéspedes.\n4. Verificar fechas, duplicados y ausencia de otra estadía activa de esos huéspedes.\n5. Incluir CU05: consultar disponibilidad y capacidad.\n6. Confirmar ingreso.\n7. Crear ESTADIA ACTIVA y una participación por huésped.\n8. Si corresponde, pasar reserva a CHECK_IN.','A1. Reserva cancelada o ya utilizada: seleccionar otra o ingreso directo.\nA2. Faltan pasajeros identificados, fechas inválidas o huésped ya alojado: corregir.\nA3. Capacidad insuficiente o conflicto: elegir otra habitación o intervalo.\nA4. No confirmar: terminar sin guardar.','Estadía activa con sus pasajeros; habitación ocupada.','La disponibilidad es una validación del flujo, no una precondición asumida como cierta.'),
'CU05':('Encargado; Administrador por herencia de interacciones','Sesión con permiso.','1. Ingresar entrada, salida y cantidad.\n2. Validar intervalo y cantidad entera positiva.\n3. Filtrar habitaciones por capacidad.\n4. Excluir reservas REGISTRADAS/CHECK_IN y estadías ACTIVA que se superpongan.\n5. Mostrar habitaciones compatibles.','A1. Fechas inválidas: corregir.\nA2. Sin resultados: mostrar listado vacío y permitir otra consulta.','Disponibilidad consultable para el intervalo.','Puede ejecutarse directamente o como inclusión de CU04, CU09 y CU11.'),
'CU06':('Encargado; Administrador por herencia de interacciones','Sesión con permiso y estadía ACTIVA.','1. Seleccionar estadía y salida real.\n2. Recuperar todos sus pasajeros.\n3. Incluir CU07: calcular cuenta individual y total.\n4. Mostrar detalle de cuenta.\n5. Confirmar cuenta y salida.\n6. Revisar posibles conflictos al extender la salida.\n7. Guardar costos individuales y salida real.\n8. Pasar estadía y reserva asociada a FINALIZADA.\n9. Liberar ocupación de habitación.','A1. Estadía no activa o salida inválida: rechazar.\nA2. Regla o tarifa sin definir: solicitar definición antes de cerrar.\nA3. No confirmar: conservar estadía activa.\nA4. Extensión de salida con conflicto: resolverlo antes de guardar.','Estadía finalizada, cuenta conservada y habitación liberada.','La liberación no elimina reservas futuras ni historial.'),
'CU07':('Invocado por CU06','Estadía activa, pasajeros identificados y regla de cobro definida.','1. Recuperar período y pasajeros.\n2. Obtener parámetros de la regla aprobada.\n3. Calcular costo de cada pasajero.\n4. Sumar los costos para obtener total.\n5. Presentar el detalle para revisión.','A1. Regla, tarifa o período inválido: no producir una cuenta confirmable.\nA2. Importe fuera del rango admitido: rechazar el cálculo.','Cuenta calculada, sin finalizar todavía la estadía.','En la demostración: noches = salida - entrada; costo individual = tarifa de prueba x noches. El caso no confirma esta fórmula.'),
'CU08':('Administrador','Sesión con permiso administrativo.','1. Seleccionar nuevo usuario o existente.\n2. Ingresar nombre de usuario.\n3. Asignar rol Administrador o Encargado.\n4. Indicar estado activo en edición.\n5. Validar y guardar.','A1. Nombre duplicado o rol inexistente: corregir.\nA2. Cambio del propio rol/estado durante sesión: rechazar en la propuesta.','Usuario guardado con un rol válido.','Las credenciales seguras pertenecen a la implementación final; el prototipo usa usuarios demo.'),
'CU09':('Encargado; Administrador por herencia de interacciones','Sesión con permiso y titular registrado.','1. Seleccionar titular y habitación.\n2. Ingresar entrada, salida y cantidad.\n3. Validar datos.\n4. Incluir CU05 para fechas y capacidad.\n5. Confirmar.\n6. Guardar reserva REGISTRADA y mostrar su número.','A1. Fecha, cantidad o titular inválidos: corregir.\nA2. Conflicto de disponibilidad: cambiar selección.\nA3. No confirmar: no crear reserva.','Reserva registrada; ocupación actual de habitación no cambia.','La reserva bloquea el intervalo futuro, no marca la habitación como ocupada físicamente.'),
'CU10':('Administrador','Sesión con permiso y período válido.','1. Seleccionar fechas desde/hasta.\n2. Consultar estadías que intersectan el período.\n3. Mostrar informe de ocupación con pasajeros y estados.\n4. Consultar reservas que intersectan el período.\n5. Mostrar titular, habitación, fechas y estado.','A1. Período inválido: corregir.\nA2. Sin datos: mostrar informe vacío, no un error.','Informes visibles para el período.','Las reservas CANCELADAS se conservan en el informe histórico con su estado.'),
'CU11':('Encargado; Administrador por herencia de interacciones','Sesión con permiso y reserva REGISTRADA.','1. Seleccionar reserva.\n2. Cambiar habitación, titular, fechas o cantidad.\n3. Validar campos.\n4. Incluir CU05 excluyendo la propia reserva del conflicto.\n5. Confirmar y guardar cambios.','A1. Reserva en otro estado: impedir modificación.\nA2. Capacidad o disponibilidad incompatibles: corregir sin perder la reserva original.\nA3. No confirmar: conservar valores originales.','Reserva actualizada y todavía REGISTRADA.','No se modifica una reserva ya usada para check-in.'),
'CU12':('Encargado; Administrador por herencia de interacciones','Sesión con permiso y reserva REGISTRADA.','1. Seleccionar reserva.\n2. Solicitar cancelación.\n3. Confirmar la decisión.\n4. Marcar CANCELADA.\n5. Liberar su bloqueo de disponibilidad sin borrar historial.','A1. Reserva en otro estado: impedir cancelación.\nA2. No confirmar: conservar reserva registrada.','Reserva cancelada, conservada en el historial.','La cancelación no se modela como extend obligatorio ni como borrado de datos.')}
