def table(heads,rows):return '| '+' | '.join(heads)+' |\n| '+' | '.join(['---']*len(heads))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)
add('# Sistema de Pasajeros de Hotel - Duerme Bien\n\nTema 6 · Luis Huenchul\n\nInforme de requerimientos y modelado')
add('## 1. Introducción\n\n### 1.1 Propósito\nDefinir qué debe hacer el sistema que reemplazará las planillas Excel del hotel Duerme Bien y relacionar requerimientos, casos de uso, procesos, datos e interfaces. Se utilizan las secciones IEEE 830 adaptadas enumeradas en el documento de definición de proyectos.\n\n### 1.2 Alcance\nHabitaciones, huéspedes, ocupación y disponibilidad, check-in, check-out, costos por pasajero, reservas, usuarios y los informes de ocupación y reservas. Se conserva el tema 6; no se agregan pagos electrónicos, restaurante, inventario ni otros servicios.\n\n### 1.3 Público objetivo\nAdministrador y encargados del hotel, equipo de desarrollo y docente.\n\n### 1.4 Definiciones\nHuésped: pasajero identificado. Reserva: alojamiento previsto para un período. Estadía: alojamiento efectivamente registrado. Participación: vínculo entre una estadía y uno de sus huéspedes. Check-in: ingreso y asignación. Check-out: cálculo de cuenta y cierre. Wireframe: estructura de pantalla. Mockup: diseño visual. Prototipo: interfaz que permite probar el flujo.')
add('## 2. Descripción general\n\n### 2.1 Perspectiva del producto\nEl sistema centraliza la información hoy mantenida en Excel. Las habitaciones conservan capacidad y orientación; las reservas y estadías conservan su historial. La disponibilidad se obtiene de los registros vigentes, en lugar de guardar un estado futuro ambiguo en la habitación.\n\n### 2.2 Funciones generales\nRegistro y edición de habitaciones, registro de huéspedes, consulta de disponibilidad, asignación de huéspedes, cierre de estadías, cálculo individual, reservas, gestión de perfiles e informes.\n\n### 2.3 Clases de usuario\nEl caso identifica Administrador y Encargado. En el diagrama de casos de uso, Administrador generaliza a Encargado y agrega las tareas administrativas. En el diagrama de clases ambos especializan a la clase abstracta Usuario para hacer visible la herencia solicitada por la pauta. En el modelo relacional esa especialización se implementa mediante USUARIO y ROL, evitando duplicar credenciales.\n\n### 2.4 Entorno operativo\nEl prototipo usa HTML, CSS y JavaScript en el navegador, con almacenamiento local. Implementa operaciones y validaciones para demostrar el diseño. La selección de usuario simula una sesión; no autentica identidades reales. El sistema final necesita servidor, base de datos, control transaccional y autenticación segura. El caso no fija motor ni infraestructura.\n\n### 2.5 Restricciones\nMantener capacidad, orientación, asignación de pasajeros, cálculo individual, ambos perfiles e informes. No inventar tarifas ni entrevistas reales. Los ejemplos son ficticios y los importes se expresan en CLP.\n\n### 2.6 Supuestos y dependencias\nSe propone una habitación completa por reserva y estadía; cada estadía identifica a todos sus pasajeros. Los intervalos se interpretan como [entrada, salida): una salida permite otra entrada ese día. Compartir habitación entre estadías, reservas de varias habitaciones, permisos exactos y regla de cobro requieren confirmación. El diseño se ajustará si la entrevista define esas condiciones de otra forma.')
add('## 3. Requerimientos\n\n### 3.1 Requerimientos funcionales\n'+table(['ID','Requerimiento','Criterio observable'],[(a,b,c) for a,b,c,*_ in requirements]))
add('### 3.2 Requerimientos no funcionales propuestos\n'+table(['ID','Criterio','Aceptación'],[('RNF01','Acceso por perfil','Rechazar una operación restringida aun si se intenta fuera de la navegación visible.'),('RNF02','Integridad de datos','Rechazar duplicados, fechas incoherentes, capacidades inválidas y pasajeros no identificados.'),('RNF03','Usabilidad','Etiquetas, navegación consistente, detalle de cuenta y mensajes concretos de corrección.'),('RNF04','Persistencia','Los datos de demostración sobreviven al recargar el navegador; el sistema final usa almacenamiento central.'),('RNF05','Consistencia concurrente','El sistema final confirma disponibilidad y guarda asignación en una transacción. El prototipo local no demuestra concurrencia entre dispositivos.'),('RNF06','Trazabilidad y mantenimiento','Conservar un código único por caso de uso y la relación con requerimientos, datos y pantallas.')]))
add('### 3.3 Matriz de permisos propuesta\n'+table(['Operación','Encargado','Administrador'],[('Acceso y consulta de disponibilidad','Sí','Sí'),('Huéspedes, reservas, check-in y check-out','Sí','Sí'),('Gestión de habitaciones','No','Sí'),('Gestión de usuarios','No','Sí'),('Informes de ocupación y reservas','No','Sí')]))
add('## 4. Reglas de negocio\n'+table(['ID','Regla','Origen'],[('RN01','Pasajeros de una estadía <= capacidad de habitación.','Derivada del control de capacidad.'),('RN02','No confirmar reservas o estadías con intervalos incompatibles en la misma habitación.','Derivada de disponibilidad.'),('RN03','Cada pasajero se registra individualmente en ESTADIA_HUESPED; no se guarda sólo una cantidad.','Derivada de registro y costo por pasajero.'),('RN04','Check-out incluye calcular cuenta por pasajero y requiere confirmación antes de cerrar.','Imagen UML del hotel y diseño del proceso.'),('RN05','Reserva REGISTRADA pasa a CHECK_IN al ingresar; al salir pasa a FINALIZADA. CANCELADA deja de bloquear disponibilidad.','Estados propuestos para gestionar reservas.'),('RN06','Sólo una estadía ACTIVA puede cerrarse. La salida libera ocupación y conserva historial.','Proceso de check-out.'),('RN07','Cada usuario tiene un rol válido: Administrador o Encargado.','Perfiles explícitos del tema 6.'),('RN08','Un huésped no se asigna a dos estadías activas simultáneas.','Propuesta de integridad de asignación.'),('RN09','No borrar reservas canceladas ni estadías finalizadas para liberar una habitación.','Propuesta para conservar los informes históricos.')]))
add('### 4.1 Cálculo de costos\nEl caso exige cálculo automático por pasajero, pero no entrega tarifa ni unidad de cobro. Para demostrar la operación se ingresa una tarifa ficticia por pasajero y noche. Las noches se calculan a partir de las fechas; costo individual = tarifa de prueba x noches y total = suma de los costos individuales. Se conserva la tarifa aplicada y el costo en cada participación; las noches comunes de la cuenta se guardan una sola vez en ESTADIA. Esto no confirma la política real de cobro. No se agregan impuestos, descuentos ni pagos que no estén en el caso.')
add('## 5. Toma de requerimientos\n\n### 5.1 Ejercicio de entrevista simulada\nLa actividad solicita entrevista simulada. El siguiente registro organiza preguntas y respuestas sustentadas en el caso escrito; no representa una conversación que haya ocurrido con el hotel. Las respuestas que no constan en el caso quedan pendientes.\n'+table(['Pregunta','Respuesta del cliente simulado basada en el caso','Trazabilidad'],[('¿Qué se quiere reemplazar?','Las planillas Excel usadas para habitaciones y pasajeros.','Propósito'),('¿Qué se registra de habitaciones?','Capacidad y orientación; se propone un número único para identificarlas.','RF01'),('¿Qué se controla de los pasajeros?','Su registro y asignación a habitaciones, ocupación y costos.','RF02-RF06'),('¿Qué usuarios existen?','Administrador y encargados del hotel.','RF07'),('¿Qué informes se necesitan?','Ocupación y reservas.','RF09'),('¿Qué tarifa y fórmula utiliza el hotel?','El caso no las define; confirmar antes de implementar el cobro final.','RF06'),('¿Se reserva una habitación completa o camas?','No consta; el diseño propone habitación completa.','RF03, RF08'),('¿Qué permisos exactos tiene cada perfil?','No consta; validar la matriz propuesta.','RF07')]))
add('### 5.2 Preguntas pendientes\n'+table(['ID','Pregunta','Afecta'],[('P01','¿Qué tipo de identificación y datos personales son obligatorios?','RF02'),('P02','¿Tarifa por noche/día? ¿Puede variar por huésped, habitación o período?','RF06'),('P03','¿Habitaciones compartidas o una habitación por estadía?','RF03, RF04'),('P04','¿Varias habitaciones por reserva?','RF08'),('P05','¿Cambios de habitación durante la estadía?','RF04'),('P06','¿Permisos definitivos por rol?','RF07'),('P07','¿Condiciones definitivas para modificar/cancelar y extender salidas?','RF05, RF08'),('P08','¿Campos y filtros exactos de informes?','RF09'),('P09','¿Entorno final, respaldo y concurrencia?','RNF04, RNF05'),('P10','¿Cuál fue la retroalimentación detallada de la Evaluación 1?','Evaluación 2')]))
add('## 6. Factibilidad\n\n### 6.1 Técnica\nEl prototipo verifica que los procesos pueden expresarse mediante formularios, reglas y relaciones entre registros. El modelo usa siete entidades relacionales y una tabla de unión para pasajeros. El sistema final requiere transacciones para impedir doble asignación, credenciales seguras y persistencia central. El navegador local permite revisar funcionalidades, pero no sustituye esas capacidades.\n\n### 6.2 De negocio\nLa propuesta responde al objetivo de centralizar el registro, evitar duplicados y consultar ocupación y reservas. No se calculan costos de implementación, ahorros ni rentabilidad porque el caso no entrega datos económicos. La factibilidad final depende de validar reglas y entorno con el cliente simulado.')
add('## 7. Modelado funcional\n\n### 7.1 Casos de uso\nUn diagrama único muestra el límite del sistema, los dos actores y CU01-CU12. Las asociaciones actor-caso son continuas y sin flecha. Las inclusiones son discontinuas, con flecha hacia el caso incluido. CU04, CU09 y CU11 incluyen consultar disponibilidad; CU06 incluye calcular cuenta. Ingreso directo extiende CU04 sólo bajo la condición sin reserva, por lo que no modifica el flujo normal. El Administrador especializa al actor Encargado mediante triángulo hueco hacia Encargado. El Huésped es una entidad atendida por los encargados, no un usuario directo del sistema.')
for id,name,rf in M['casos']:
 actor,pre,flow,alt,post,note=specs[id];add(f'### {id} - {name}\n\nActor: {actor}.\n\nPrecondiciones: {pre}\n\nFlujo principal:\n{flow}\n\nAlternativas y errores:\n{alt}\n\nPostcondición: {post}\n\nTrazabilidad: {rf}.\n\nObservación: {note}')
add('### 7.2 Procesos\nLos flujos muestran inicio/fin, entradas/salidas, acciones, decisiones con salidas etiquetadas, retornos por error y finalización sin cambios. Se separan registrar reserva, check-in, check-out y modificar/cancelar reserva. Cada decisión tiene dos salidas. Cancelar una operación conserva el registro original; cancelar una reserva cambia su estado, no borra su historial.')
add('## 8. Clases y modelo de datos\n\n### 8.1 Clases de dominio\nUsuario es una clase abstracta y Administrador/Encargado heredan sus datos de acceso. Administrador genera informes de ocupación y reservas. Un Huesped puede ser titular de reservas y tener participaciones históricas; cada Reserva se asigna a una Habitacion y puede originar una Estadia. Habitacion aloja estadías y Estadia compone una o más ParticipacionEstadia con rombo sólido. Las demás relaciones son asociaciones. Cada relación incluye un verbo y multiplicidades junto a sus extremos; las clases muestran atributos privados, métodos públicos y tipos.')
add('### 8.2 Diccionario y claves\n'+table(['Entidad','Clave primaria','Referencias y unicidad','Uso'],[('ROL','id_rol','nombre único','Administrador o Encargado.'),('USUARIO','id_usuario','id_rol -> ROL; nombre_usuario único','Perfil, estado y credencial del sistema final.'),('HABITACION','id_habitacion','numero único','Capacidad positiva y orientación.'),('HUESPED','id_huesped','identificacion única','Identidad, nombres y apellidos.'),('RESERVA','id_reserva','id_habitacion -> HABITACION; id_huesped_titular -> HUESPED','Fechas, cantidad y estado.'),('ESTADIA','id_estadia','id_habitacion -> HABITACION; id_reserva opcional y único -> RESERVA','Fechas reales/previstas, estado y noches cobradas.'),('ESTADIA_HUESPED','(id_estadia, id_huesped)','id_estadia -> ESTADIA; id_huesped -> HUESPED','Cada pasajero; tarifa aplicada y costo histórico.')]))
add('### 8.3 Cardinalidades y restricciones\n'+table(['Relación','Cardinalidad','Interpretación'],[('ROL - USUARIO','1 : 0..*','Un usuario tiene exactamente un rol; un rol puede no tener usuarios.'),('HABITACION - RESERVA','1 : 0..*','Una reserva tiene una habitación; una habitación tiene muchas reservas en el tiempo.'),('HABITACION - ESTADIA','1 : 0..*','Una estadía tiene una habitación; una habitación conserva distintas estadías históricas.'),('HUESPED - RESERVA','1 : 0..*','Una reserva tiene un titular; un huésped puede titularizar varias reservas.'),('RESERVA - ESTADIA','0..1 : 0..1','Una reserva origina como máximo una estadía; puede existir estadía sin reserva.'),('ESTADIA - ESTADIA_HUESPED','1 : 1..*','Cada estadía registrada tiene uno o más pasajeros.'),('HUESPED - ESTADIA_HUESPED','1 : 0..*','Cada participación identifica un huésped; el huésped puede alojarse varias veces.')]))
add('El modelo lógico usa notación pata de cuervo, claves PK/FK/UQ y tipos de datos propuestos. NULL identifica información todavía no definida: reserva de origen de un ingreso directo, salida real de una estadía activa y resultados de cobro antes de cerrar. El resto de los campos de identificación y referencias obligatorias debe ser NOT NULL. Las fechas deben respetar salida > entrada; capacidad y cantidad son enteros positivos. La pareja de ESTADIA_HUESPED es única. Capacidad, superposición y mínimo de un pasajero requieren validación conjunta/transaccional: una FK aislada no garantiza esas reglas.')
add('### 8.4 Normalización\n\nPrimera forma normal: cada celda almacena un valor. Los pasajeros de una estadía no se guardan en una lista dentro de HABITACION; cada participación es una fila de ESTADIA_HUESPED.\n\nSegunda forma normal: las tablas de identificación tienen claves simples. En la tabla de unión, los datos personales dependen de id_huesped y se mantienen en HUESPED; fechas y noches comunes dependen de id_estadia y se mantienen en ESTADIA. La tarifa aplicada y el costo histórico se vinculan a la participación completa.\n\nTercera forma normal: nombre del rol está en ROL; capacidad y orientación están en HABITACION; nombres del titular están en HUESPED. Esos datos no se repiten en RESERVA o ESTADIA. La ocupación y el total de cuenta se derivan, en lugar de duplicarlos como fuentes de verdad. El costo individual se conserva como resultado histórico de una regla de cobro aplicada; la tarifa de referencia no es una tabla de precios del hotel. La regla real podría requerir otra estructura una vez validada.')
add('## 9. Sketch, wireframes, mockups y prototipo\n\nSketch: distribución inicial de cabecera, navegación, indicadores, formulario y resultados. Wireframes: nueve pantallas con campos, controles, listados y acciones sin depender del estilo visual. Mockups: las mismas nueve pantallas con identidad gráfica y ejemplos de datos. Prototipo: navegación y operaciones con persistencia local y validaciones del modelo.\n'+table(['Pantalla','Datos y acciones principales','Casos de uso'],[('Acceso','Selección de usuario demo y perfil asignado.','CU01'),('Disponibilidad','Fechas, cantidad, capacidad y habitaciones compatibles; ocupación actual.','CU05'),('Habitaciones','Número, capacidad, orientación; registrar y editar.','CU02'),('Huéspedes','Identificación, nombres y apellidos; registro y selección posterior.','CU03'),('Reservas','Titular, habitación, fechas, cantidad; registrar, modificar, cancelar.','CU09, CU11, CU12'),('Check-in','Reserva o ingreso directo; habitación, fechas y cada pasajero.','CU04'),('Check-out','Estadía, salida, tarifa ficticia, cálculo individual, total y confirmación.','CU06, CU07'),('Informes','Período, ocupación y reservas con estados.','CU10'),('Usuarios','Nombre único, perfil y estado; registrar y editar.','CU08')]))
add('### 9.1 Archivos editables\nLos diagramas y todas las vistas de interfaz tienen archivos nativos .drawio con figuras, textos y conectores unidos a los elementos; no son imágenes pegadas en un lienzo. La galería permite abrir cada archivo directamente en diagrams.net. interfaces.drawio reúne sketch y las dieciocho vistas de wireframe/mockup. Los enlaces de edición de código usan github.dev. El material de mockups menciona distintas plataformas, incluido Cacoo, Balsamiq y prototipos HTML/CSS. Se conserva diagrams.net porque es el formato del repositorio de referencia. No se afirma haber creado proyectos en plataformas distintas.')
add('### 9.2 Alcance implementado\nEl prototipo registra y edita habitaciones, identifica huéspedes, gestiona reservas, realiza check-in con o sin reserva, registra cada pasajero, calcula noches a partir de fechas y conserva costos individuales al salir. Controla las operaciones por rol demo y genera informes por período. No implementa autenticación productiva, servidor, base de datos central ni exclusión concurrente entre dispositivos. Estas diferencias se mantienen visibles en la documentación para no presentar una maqueta como un sistema instalado en el hotel.')
add('## 10. Planificación Kanban\n\nEl tablero conserva tareas técnicas terminadas, artefactos en revisión y decisiones pendientes. Terminar la implementación no equivale a aprobación del docente. No se inventan integrantes ni plazos. La pauta de la Evaluación 2 fue revisada; las decisiones sobre identificación, cobro, permisos, habitación compartida y entorno, además de la retroalimentación detallada de la Evaluación 1, permanecen por validar.')
add('## 11. Trazabilidad\n'+table(['RF','Casos de uso','Clases/entidades','Pantallas'],[(a,d,e,f) for a,b,c,d,e,f in requirements]))
add('### 11.1 Verificación\nLas pruebas del motor comprueban acceso restringido, duplicados, capacidad, fechas, solapamiento, intervalos contiguos, modificación/cancelación de reservas, identificación de todos los pasajeros, check-in directo, repetición de operaciones, costos por huésped, liberación de ocupación e informes por fechas. La revisión del modelado comprueba códigos de casos, cobertura de requisitos, conectores, decisiones y cardinalidades. Las pruebas técnicas no reemplazan la aprobación académica ni la validación de reglas del hotel.')
add('## 12. Referencias\n\nMateriales del profesor utilizados: Evaluación_2_MSI.pdf; Definición de proyectos(2).docx; UML_CASOS_DE_USO_2(2).jpg; UML_CASOS_DE_USO(2).jpg; CASOS_DE_USO_como_iniciar(2).pdf; CASOS_DE_USO_extend_y_include(2).pdf; diagrama_de_procesos(2).jpg; Diagramas de Clase(2).pdf; GUIA_diagramas_de_clase(2).pdf; MODELO_E_R_NORMALIZACION(1).pdf; MOCKUP_COMPLETO(2).pdf; Github_Git_VSCode(1).docx. Se conservan los originales en fuentes/.\n\nReferencias técnicas de notación y diseño consultadas para la revisión:\n1. OMG. UML 2.5.1: https://www.omg.org/spec/UML/2.5.1\n2. draw.io. Clases UML: https://www.drawio.com/docs/diagram-types/uml/class-diagrams/\n3. draw.io. Modelo entidad-relación: https://www.drawio.com/docs/diagram-types/entity-relationship-tables/\n4. Balsamiq. Wireframes: https://balsamiq.com/blog/what-are-wireframes/\n5. Referencia de organización y prototipo inicial: https://github.com/Yutre3/diego\n\nEstas referencias aportan notación y técnicas, no funciones nuevas del negocio. El alcance proviene del tema 6 y de la pauta de Evaluación 2. No se agregan funciones que no estén sustentadas por esos materiales.')
