styles['BodyText'].fontSize=9;styles['BodyText'].leading=14;styles['BodyText'].spaceAfter=5;styles['Heading1'].fontSize=20;styles['Heading2'].fontSize=14;styles['Heading2'].spaceBefore=14;styles['Heading3'].fontSize=11;styles['Heading3'].spaceBefore=10
story=[]
def p(s,style='BodyText'):return Paragraph(html.escape(s).replace('\n','<br/>'),styles[style])
def add_table(lines):
 rows=[line.strip().strip('|').split('|') for line in lines if '---' not in line]
 width=499/len(rows[0]);cells=[[p(cell.strip()) for cell in row] for row in rows];t=Table(cells,colWidths=[width]*len(rows[0]),repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e6eff4')),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#bdcbd4')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story.extend([t,Spacer(1,12)])
lines=text.splitlines();i=0;buffer=[]
def flush():
 if buffer:story.append(p('\n'.join(buffer)));buffer.clear()
while i<len(lines):
 line=lines[i]
 if not line.strip():flush();i+=1;continue
 if line.startswith('|'):
  flush();rows=[]
  while i<len(lines) and lines[i].startswith('|'):rows.append(lines[i]);i+=1
  add_table(rows);continue
 if line.startswith('#'):
  flush();level=len(line)-len(line.lstrip('#'));story.append(p(line.lstrip('# ').strip(),'Heading'+str(min(level,3))))
 else:buffer.append(line)
 i+=1
flush()
def footer(c,doc):c.setFont('DV',8);c.setFillColor(colors.HexColor('#546778'));c.drawString(48,25,'Duerme Bien · Tema 6 · Luis Huenchul');c.drawRightString(547,25,str(doc.page))
